const res = $input.first().json || {};
const topics = (res.topic_list && res.topic_list.topics) || [];
const maintenant = Date.now();
const out = [];
for (const t of topics) {
  const titre = String(t.title || "");
  if (t.pinned === true) continue;
  if (/^About the/i.test(titre)) continue;
  const ref = Date.parse(t.last_posted_at || t.created_at || "") || 0;
  const jours = (maintenant - ref) / 86400000;
  if (jours > 21) continue;
  out.push({ json: {
    topic_id: String(t.id),
    titre: titre,
    url: "https://community.n8n.io/t/" + (t.slug || "sujet") + "/" + t.id,
    cree_le: String(t.created_at || "").slice(0, 10),
    reponses: t.posts_count || 0
  } });
}
// Plafond volontaire : le reste sera pris a l execution suivante, pas perdu.
return out.slice(0, 12);

const NL = String.fromCharCode(10);
const GUILLEMET = String.fromCharCode(34);
const profil = "Profil du candidat : decrivez ici le poste vise, les competences, la mobilite, les langues et les criteres eliminatoires. Plus ce paragraphe est precis, moins le scoring se trompe.";
  const consigne = "Tu évalues si un message du forum n8n (catégorie Jobs) est une opportunité pertinente pour ce candidat. "
  + "Réponds UNIQUEMENT par un objet JSON, sans texte autour et sans bloc de code, au format exact : "
  + '{"pertinent": true, "score": 7, "type_poste": "n8n developer", "remote": "full remote", "langue": "anglais", "budget": "non précisé", "pourquoi": "une phrase", "signaux_negatifs": "une phrase ou vide"} '
  + "score = entier de 0 à 10. 0 = hors sujet, 10 = correspondance parfaite. "
  + "Mets pertinent = false et un score bas si le message est une CANDIDATURE (quelqu'un qui cherche du travail) et non une OFFRE de mission ou d'emploi. "
  + "Rédige pourquoi et signaux_negatifs en français.";
const out = [];
for (const item of $input.all()) {
  const d = item.json || {};
  const posts = (d.post_stream && d.post_stream.posts) || [];
  const premier = posts[0] || {};
  let corps = String(premier.cooked || "");
  corps = corps.split("<br>").join(NL).split("<br/>").join(NL).split("<br />").join(NL);
  corps = corps.split("</p>").join(NL).split("</li>").join(NL);
  corps = corps.replace(/<[^>]+>/g, "");
  corps = corps.split("&nbsp;").join(" ").split("&amp;").join("&").split("&lt;").join("<").split("&gt;").join(">");
  corps = corps.split("&#39;").join("'").split("&quot;").join(GUILLEMET);
  const bouts = [];
  for (const ligne of corps.split(NL)) {
    const propre = ligne.trim();
    if (propre.length > 0) { bouts.push(propre); }
  }
  corps = bouts.join(NL).slice(0, 4000);
  const titre = String(d.title || "");
  const payload = {
    model: "claude-sonnet-5",
    max_tokens: 700,
    system: profil + " " + consigne,
    messages: [{ role: "user", content: "TITRE : " + titre + NL + "AUTEUR : " + (premier.username || "?") + NL + "DATE : " + String(d.created_at || "").slice(0, 10) + NL + NL + "MESSAGE :" + NL + corps }]
  };
  out.push({ json: {
    topic_id: String(d.id),
    titre: titre,
    url: "https://community.n8n.io/t/" + (d.slug || "sujet") + "/" + d.id,
    auteur: String(premier.username || ""),
    cree_le: String(d.created_at || "").slice(0, 10),
    claudeBody: JSON.stringify(payload)
  } });
}
return out;

const prep = $("Preparer appel Claude").all();
const reponses = $input.all();
const out = [];
for (let i = 0; i < reponses.length; i++) {
  const meta = (prep[i] && prep[i].json) || {};
  let txt = "";
  const blocs = (reponses[i].json && reponses[i].json.content) || [];
  if (Array.isArray(blocs)) {
    for (const b of blocs) { if (b && b.type === "text") { txt += String(b.text || ""); } }
  }
  let v = {};
  try {
    v = JSON.parse(txt);
  } catch (e) {
    const a = txt.indexOf("{");
    const z = txt.lastIndexOf("}");
    if (a >= 0 && z > a) {
      try { v = JSON.parse(txt.slice(a, z + 1)); } catch (e2) { v = {}; }
    }
  }
  const n = Number(v.score);
  const score = Number.isFinite(n) ? n : 0;
  out.push({ json: {
    topic_id: meta.topic_id,
    titre: meta.titre,
    url: meta.url,
    auteur: meta.auteur,
    cree_le: meta.cree_le,
    score: score,
    pertinent: v.pertinent === true && score >= 6,
    type_poste: String(v.type_poste || ""),
    remote: String(v.remote || ""),
    langue: String(v.langue || ""),
    budget: String(v.budget || ""),
    pourquoi: String(v.pourquoi || ""),
    signaux_negatifs: String(v.signaux_negatifs || ""),
    analyse_ok: txt.length > 0,
    date_vue: new Date().toISOString().slice(0, 10)
  } });
}
return out;

// Termes distinctifs seulement. "Lineo" seul est ecarte : verifie le 2026-08-05,
// il remonte 2 faux positifs (sujets XML de 2020) sans lien avec le candidat.
return [{ json: { q: "Biribin" } }, { json: { q: "lineobiribin" } }];

const out = [];
const deja = {};
for (const item of $input.all()) {
  const d = item.json || {};
  const posts = Array.isArray(d.posts) ? d.posts : [];
  const sujets = Array.isArray(d.topics) ? d.topics : [];
  const titres = {};
  for (const t of sujets) { titres[t.id] = t.title; }
  for (const p of posts) {
    const cle = "mention-" + p.id;
    if (deja[cle]) { continue; }
    deja[cle] = true;
    out.push({ json: {
      topic_id: cle,
      titre: "Mention : " + (titres[p.topic_id] || ("sujet " + p.topic_id)),
      url: "https://community.n8n.io/t/" + p.topic_id + "/" + (p.post_number || 1),
      auteur: String(p.username || ""),
      extrait: String(p.blurb || "").slice(0, 500),
      cree_le: String(p.created_at || "").slice(0, 10),
      score: 10,
      pertinent: true,
      date_vue: new Date().toISOString().slice(0, 10)
    } });
  }
}
return out;

// Sans ce rattachement, le marquage ecrivait une ligne VIDE (constate le
// 2026-08-07, ligne 24 de la data table) : la cle de deduplication etait nulle,
// donc le sujet aurait ete reanalyse et repousse a chaque tournee, sans fin.
const sujets = $('🔀 Pertinent ?').all();
const reponses = $input.all();
const out = [];
for (let i = 0; i < reponses.length; i++) {
  const s = (sujets[i] && sujets[i].json) || {};
  // Jamais de ligne sans cle : mieux vaut reanalyser le sujet demain que
  // polluer la table avec une entree qui ne dedupliquera jamais rien.
  if (!s.topic_id) continue;
  out.push({ json: { ...s, inbox_added: reponses[i].json && reponses[i].json.added, inbox_already: reponses[i].json && reponses[i].json.already } });
}
return out;

const mentions = $('Mentions jamais vues').all();
const reponses = $input.all();
const out = [];
for (let i = 0; i < reponses.length; i++) {
  const m = (mentions[i] && mentions[i].json) || {};
  if (!m.topic_id) continue;
  out.push({ json: m });
}
return out;
